import { useState } from 'react'
import { PlaygroundCard } from './components/PlaygroundCard'
import { useHookGallery } from './hooks/useHookGallery'

export default function HooksPlayground() {
  const [filter, setFilter] = useState('')
  const hooks = useHookGallery(filter)

  return (
    <main className="hooks-playground">
      <header>
        <h1>Hooks demo</h1>
        <p>Toggle hooks to preview how they behave inside the Arcade preview.</p>
      </header>
      <section>
        {hooks.map(hook => (
          <PlaygroundCard key={hook.id} hook={hook} />
        ))}
      </section>
    </main>
  )
}

